// Some portions generated by Codex
package org.eclipse.rdf4j.http.server.security;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.concurrent.atomic.AtomicBoolean;

import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

import jakarta.servlet.http.Cookie;

class RequestIntegrityFilterTest {

	private final RequestIntegrityFilter filter = new RequestIntegrityFilter();

	@Test
	void deniesCrossSiteSimpleMutationsWithBasicCookieOrNoAuthentication() throws Exception {
		for (int mode = 0; mode < 3; mode++) {
			MockHttpServletRequest request = request("POST");
			request.addHeader("Origin", "https://attacker.example");
			request.addHeader("Sec-Fetch-Site", "cross-site");
			if (mode == 0) {
				request.addHeader("Authorization", "Basic YWxpY2U6c2VjcmV0");
			} else if (mode == 1) {
				request.setCookies(new Cookie("JSESSIONID", "ambient-authority"));
			}
			assertDenied(request);
		}
	}

	@Test
	void permitsSafeSameOriginAndExplicitCorsApiRequests() throws Exception {
		MockHttpServletRequest safe = request("GET");
		safe.addHeader("Origin", "https://attacker.example");
		safe.addHeader("Sec-Fetch-Site", "cross-site");
		assertAllowed(safe);

		MockHttpServletRequest sameOrigin = request("POST");
		sameOrigin.addHeader("Origin", "https://example.org");
		sameOrigin.addHeader("Sec-Fetch-Site", "same-origin");
		assertAllowed(sameOrigin);

		MockHttpServletRequest explicitApi = request("DELETE");
		explicitApi.addHeader("Origin", "https://client.example");
		explicitApi.addHeader("Sec-Fetch-Site", "cross-site");
		explicitApi.addHeader(RequestIntegrityFilter.EXPLICIT_REQUEST_HEADER, "true");
		assertAllowed(explicitApi);
	}

	@Test
	void definesNoOriginRequestsAsNonBrowserApiTraffic() throws Exception {
		MockHttpServletRequest basic = request("POST");
		basic.addHeader("Authorization", "Basic YWxpY2U6c2VjcmV0");
		assertAllowed(basic);

		MockHttpServletRequest cookie = request("PUT");
		cookie.setCookies(new Cookie("JSESSIONID", "api-session"));
		assertAllowed(cookie);

		MockHttpServletRequest unauthenticatedLoopback = request("DELETE");
		unauthenticatedLoopback.setRemoteAddr("127.0.0.1");
		assertAllowed(unauthenticatedLoopback);
	}

	@Test
	void rejectsMalformedNullDuplicateAndCrossOriginRefererValues() throws Exception {
		MockHttpServletRequest malformed = request("POST");
		malformed.addHeader("Origin", "https://example.org/path");
		assertDenied(malformed);

		MockHttpServletRequest nullOrigin = request("POST");
		nullOrigin.addHeader("Origin", "null");
		assertDenied(nullOrigin);

		MockHttpServletRequest duplicate = request("POST");
		duplicate.addHeader("Origin", "https://example.org");
		duplicate.addHeader("Origin", "https://attacker.example");
		assertDenied(duplicate);

		MockHttpServletRequest referer = request("POST");
		referer.addHeader("Referer", "https://attacker.example/form");
		assertDenied(referer);

		MockHttpServletRequest contradictoryFetchMetadata = request("POST");
		contradictoryFetchMetadata.addHeader("Origin", "https://example.org");
		contradictoryFetchMetadata.addHeader("Sec-Fetch-Site", "cross-site");
		contradictoryFetchMetadata.addHeader(RequestIntegrityFilter.EXPLICIT_REQUEST_HEADER, "true");
		assertDenied(contradictoryFetchMetadata);

		MockHttpServletRequest contradictoryReferer = request("POST");
		contradictoryReferer.addHeader("Origin", "https://example.org");
		contradictoryReferer.addHeader("Referer", "https://attacker.example/form");
		assertDenied(contradictoryReferer);

		MockHttpServletRequest sameOriginRefererWithComma = request("POST");
		sameOriginRefererWithComma.addHeader("Referer", "https://example.org/form,a");
		assertAllowed(sameOriginRefererWithComma);
	}

	@Test
	void normalizesDefaultPortsAndRejectsSiblingOrigins() throws Exception {
		MockHttpServletRequest defaultPort = request("PATCH");
		defaultPort.addHeader("Origin", "https://example.org:443");
		assertAllowed(defaultPort);

		MockHttpServletRequest sibling = request("PATCH");
		sibling.addHeader("Origin", "https://sub.example.org");
		assertDenied(sibling);
	}

	private MockHttpServletRequest request(String method) {
		MockHttpServletRequest request = new MockHttpServletRequest(method,
				"/rdf4j-server/repositories/test/statements");
		request.setScheme("https");
		request.setSecure(true);
		request.setServerName("example.org");
		request.setServerPort(443);
		request.setContextPath("/rdf4j-server");
		return request;
	}

	private void assertAllowed(MockHttpServletRequest request) throws Exception {
		MockHttpServletResponse response = new MockHttpServletResponse();
		AtomicBoolean invoked = new AtomicBoolean();
		filter.doFilter(request, response, (req, resp) -> invoked.set(true));
		assertThat(invoked).isTrue();
		assertThat(response.getStatus()).isEqualTo(200);
	}

	private void assertDenied(MockHttpServletRequest request) throws Exception {
		MockHttpServletResponse response = new MockHttpServletResponse();
		AtomicBoolean invoked = new AtomicBoolean();
		filter.doFilter(request, response, (req, resp) -> invoked.set(true));
		assertThat(invoked).isFalse();
		assertThat(response.getStatus()).isEqualTo(403);
	}
}
